select n.id as id from notes n  left join (select rank_copy_n.copied_from_note_id as note_id, count(*) as metric from notes rank_copy_n where rank_copy_n.copied_from_public = true and rank_copy_n.copied_from_note_id is not null group by rank_copy_n.copied_from_note_id) rank_copies on rank_copies.note_id = n.id  left join (select rank_like.note_id as note_id, count(*) as metric from public_note_likes rank_like group by rank_like.note_id) rank_likes on rank_likes.note_id = n.id  left join (select rank_view.entity_id as note_id, count(*) as metric from analytics_events rank_view where rank_view.event_type = 'PUBLIC_NOTE_VIEWED' and rank_view.entity_id is not null group by rank_view.entity_id) rank_views on rank_views.note_id = n.id  where n.visibility = 'PUBLIC' and (coalesce(rank_copies.metric, 0) >= 3 or coalesce(rank_views.metric, 0) >= 20)  order by coalesce(rank_copies.metric, 0) desc, coalesce(rank_views.metric, 0) desc, coalesce(rank_likes.metric, 0) desc, n.created_at desc, n.id asc fetch first ? rows only